{"path":"/c/Users/Nefs/Projects/CompendiumSite/static/css/tekttribe.css","content":"/* TekTribe Chronicles - Custom Aesthetic */
/* Color Doctrine: Natural + Overseer Tek */

:root {
  /* Natural (Earthy) */
  --natural-green: #2d4a3e;
  --natural-brown: #5c4033;
  --natural-cream: #f5f0e6;

  /* Artificial/Overseer Tek (Neutral) */
  --tekt-cyan: #00f0ff;
  --tekt-aurora: linear-gradient(135deg, #00f0ff, #0080ff);
  --tekt-gold: #d4af37;
  --tekt-ice-blue: #e0f7ff;

  /* Dark Mode Default */
  --bg-primary: #0a0e0f;
  --bg-secondary: #121819;
  --text-primary: #e8e8e8;
  --text-secondary: #a0a0a0;
  --border-color: #2a3536;
}

/* Typography */
body {
  font-family: 'Georgia', 'Times New Roman', serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.8;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Helvetica Neue', 'Arial', sans-serif;
  letter-spacing: -0.02em;
  margin-top: 2em;
  margin-bottom: 1em;
}

h1 {
  color: var(--tekt-cyan);
  font-size: 2.5em;
  border-bottom: 2px solid var(--tekt-gold);
  padding-bottom: 0.5em;
}

h2 {
  color: var(--tekt-gold);
  font-size: 1.8em;
}

h3 {
  color: var(--natural-green);
  background: var(--tekt-ice-blue);
  padding: 0.3em 1em;
  border-left: 3px solid var(--tekt-cyan);
}

/* PaperMod theme overrides for dark mode */
.dark-mode .content {
  background: var(--bg-secondary) !important;
}

/* Navigation */
.main-menu .menu {
  background: var(--bg-secondary) !important;
  border-bottom: 1px solid var(--tekt-gold) !important;
}

.main-menu .menu ul li a {
  color: var(--text-primary) !important;
  font-family: 'Helvetica Neue', sans-serif;
  font-weight: 500;
  padding: 0.7em 1em !important;
  transition: all 0.3s ease;
}

.main-menu .menu ul li a:hover {
  background: var(--tekt-cyan) !important;
  color: var(--bg-primary) !important;
}

/* Tables */
table {
  width: 100%;
  border-collapse: collapse;
  margin: 1.5em 0;
}

table th, table td {
  padding: 0.8em;
  border: 1px solid var(--border-color);
  text-align: left;
}

table th {
  background: var(--natural-green);
  color: var(--tekt-cyan);
  font-family: 'Helvetica Neue', sans-serif;
}

/* Code blocks */
pre, code {
  font-family: 'Courier New', monospace;
}

pre {
  background: #0d1111;
  border: 1px solid var(--tekt-cyan);
  border-radius: 4px;
  padding: 1.5em;
  overflow-x: auto;
}

code {
  background: var(--tekt-ice-blue);
  color: var(--natural-brown);
  padding: 0.2em 0.4em;
  border-radius: 3px;
}

/* Callouts */
blockquote {
  border-left: 4px solid var(--tekt-gold);
  margin: 1.5em 0;
  padding: 1em 1.5em;
  background: var(--tekt-ice-blue);
  color: var(--natural-brown);
  font-style: italic;
}

/* Links */
a {
  color: var(--tekt-cyan);
  text-decoration: none;
  transition: color 0.3s ease;
}

a:hover {
  color: var(--tekt-gold);
  text-decoration: underline;
}

/* Footer */
.footer {
  background: var(--natural-green) !important;
  color: var(--tekt-cyan) !important;
  font-family: 'Helvetica Neue', sans-serif;
}

.footer p {
  margin: 0.5em 0;
}

/* Responsive */
@media (max-width: 768px) {
  h1 {
    font-size: 1.8em;
  }

  h2 {
    font-size: 1.5em;
  }

  .main-menu .menu ul {
    display: flex !important;
    flex-wrap: wrap !important;
    justify-content: center !important;
  }

  .main-menu .menu ul li {
    flex: 1 0 45% !important;
  }
}
